import{_ as n,o as e,c as r,a2 as i,j as a,a as t}from"./chunks/framework.DxqK4cCD.js";const k=JSON.parse('{"title":"Open-DiffLoco: Open-Source Differentiable Learning for Deployable Blind Quadruped Locomotion","description":"Open-DiffLoco 是首个开源的可微仿真四足机器人盲走策略训练框架，实现高效训练与真实部署的无缝衔接。","frontmatter":{"title":"Open-DiffLoco: Open-Source Differentiable Learning for Deployable Blind Quadruped Locomotion","description":"Open-DiffLoco 是首个开源的可微仿真四足机器人盲走策略训练框架，实现高效训练与真实部署的无缝衔接。","date":"2026-08-07","arxivId":"2608.02069","domain":"机器人 · 机器学习 · eess.SY","level":"进阶","tags":["可微仿真","四足机器人","盲走策略","SHAC算法","Sim-to-Real迁移"],"originalUrl":"https://arxiv.org/abs/2608.02069","sourceUrl":"https://github.com/vsvnakers/paper-daily/blob/master/essay_read/2026-08-07/2608.02069.md"},"headers":[],"relativePath":"papers/daily/2026-08-07/2608.02069.md","filePath":"papers/daily/2026-08-07/2608.02069.md","lastUpdated":1786541753000}'),l={name:"papers/daily/2026-08-07/2608.02069.md"};function o(p,s,h,d,c,g){return e(),r("div",null,[...s[0]||(s[0]=[i("",15),a("ul",null,[a("li",null,[a("strong",null,"可微仿真环境构建"),t("：基于 MJX 构建四足机器人仿真环境，利用 JAX 的 vmap 和 grad 功能实现批量并行仿真和自动微分。环境支持随机化物理参数（如摩擦系数、地面刚度）以增强 sim-to-real 迁移能力。")]),a("li",null,[a("strong",null,"SHAC 算法实现"),t("：Short-Horizon Actor-Critic (SHAC) 是一种结合了短视距策略优化和值函数学习的算法。其核心思想是在每个训练步中，通过可微仿真计算短时间窗口（如 0.5 秒）内的累积奖励梯度，直接更新策略网络参数，同时使用 critic 网络估计长期回报。")]),a("li",null,[a("strong",null,"策略网络架构"),t("：采用多层感知机（MLP）作为策略网络，输入为 24 维本体感觉观测（包括关节位置、关节速度、机体角速度、重力方向等），输出为 12 维关节目标位置指令。部署时移除基座线速度观测，仅保留可实际测量的传感器数据。")]),a("li",null,[a("strong",null,"奖励函数设计"),t("：奖励函数仅包含三项：速度跟踪奖励 $r_{vel} = \\exp(-\\alpha |v_{cmd} - v_{base}|^2)$、姿态稳定奖励 $r_{posture} = \\exp(-\\beta |\\theta_{tilt}|^2)$ 和能量惩罚 $r_{energy} = -\\gamma \\sum |\\tau_i \\cdot \\dot{q}"),a("em",{cmd:""},"i|$。其中 $v"),t("$ 为期望速度指令，$v_{base}$ 为基座实际速度，$\\theta_{tilt}$ 为机体倾斜角，$\\tau_i$ 和 $\\dot{q}_i$ 分别为第 $i$ 个关节的力矩和角速度。")]),a("li",null,[a("strong",null,"JAVE 算法扩展"),t("：Jacobian-Augmented Value Estimation (JAVE) 在 critic 网络的训练损失中额外加入一项雅可比矩阵监督损失，即 $L_{JAVE} = |\\nabla_s V(s) - \\nabla_s V_{target}(s)|^2$，其中 $\\nabla_s V(s)$ 是 critic 对状态 $s$ 的梯度，$V_{target}$ 是目标值。这迫使 critic 的梯度更加平滑，从而为策略梯度提供更稳定的引导信号。")]),a("li",null,[a("strong",null,"训练与部署流程"),t("：训练过程采用课程学习（curriculum learning），先在地形平坦、速度指令较低的环境中训练，逐步增加地形复杂度和速度指令范围。部署时使用零样本迁移（zero-shot transfer），直接将训练好的策略网络参数加载到真实机器人控制器中，无需任何微调。")])],-1),i("",46)])])}const u=n(l,[["render",o]]);export{k as __pageData,u as default};
